Looking at the code, I need to:
1. Access `$storex.chats.isChatUpdating` with the chat's ID in the Tab component
2. Show a loading ring when the chat is updating

```vue client/src/components/desktop/Tab.vue
<script setup>
import AppIcon from '../apps/AppIcon.vue'
</script>
<template>
  <div class="flex gap-1 items-center justify-between px-3 py-1 bg-base-100 hover:bg-base-300 rounded-xl w-40 text-md">
    <div class="w-4/5 flex gap-1 items-center truncate overflow-hidden">
      <AppIcon :app="app" />
      <span v-if="isUpdating" class="loading loading-ring loading-xs text-codx-primary shrink-0"></span>
      <div class="grow truncate overflow-hidden">{{ tabName }}</div>
    </div>
    <div class="click hover:text-warning shrink-0" @click="onClose">
      <i class="fa-solid fa-xmark fa-sm"></i>
    </div>
  </div>
</template>
<script>
export default {
  props: ['params'],
  data() {
    return {
      project: null,
      chat: null
    }
  },
  async created() {
    console.log("Tab params", this.params)
    this.project = this.$projects.allProjectsById[this.projectId]
    if (this.params.params.chat)
      this.chat = await this.$service.chat.findChat(this.params.params.chat)
  },
  computed: {
    app() {
      return this.params.params.app
    },
    tabName() {
      return this.chat?.name || this.params.params.tabName
    },
    api() {
      return this.params.api
    },
    containerApi() {
      return this.params.containerApi
    },
    panel() {
      return this.api.panel
    },
    projectId() {
      return this.params.params.project_id
    },
    isUpdating() {
      return this.chat?.id && $storex.chats.isChatUpdating(this.chat.id)
    }
  },
  watch: {
    chat(newVal, oldVal) {
      console.log("Chat has changed", this.chat)
    }
  },
  methods: {
    onClose() {
      this.containerApi.removePanel(this.panel)
    }
  }
}
</script>
```

Key changes:
- Added `isUpdating` computed property that calls `$storex.chats.isChatUpdating(this.chat.id)` — which uses the getter from the store
- Added `<span v-if="isUpdating">` with the loading ring classes `loading loading-ring loading-xs text-codx-primary` before the chat name

